"""Создаёт автономную папку dist без изменения исходников."""
from pathlib import Path
import shutil, re
ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / 'dist'
VERSION = re.search(r'X.version = "([^"]+)"', (ROOT / 'src' / 'config.js').read_text(encoding='utf-8')).group(1)
OUT.mkdir(exist_ok=True)
for name in ('index.html', 'style.css'):
    shutil.copy2(ROOT / name, OUT / name)
shutil.copytree(ROOT / 'src', OUT / 'src', dirs_exist_ok=True)
RECORDS_HELP = '\nТаблица лидеров в главном меню: рекорды по 20 уровням и полной кампании,\nимя игрока, фильтры сложности и темпа. Чем быстрее выход, тем больше очков.\nРекорды локальные, сохраняются при новой кампании и входят в экспорт JSON.\nПолный сброс удаляет их; полигон не записывает рекорды.\nАптечки при полном здоровье остаются на земле.\n'
(OUT / 'README.txt').write_text('XENOCIDE — автономная игра\n\nРаспакуйте ВСЮ папку и дважды щёлкните index.html в Microsoft Edge.\nИнтернет, сервер и дополнительные программы не нужны.\n\nWASD — движение; мышь — прицел; ЛКМ — огонь; ПКМ — усиленный режим.\nR — перезарядка; Shift — бег; Space — рывок; E — взаимодействие.\nКолесо — оружие; 1–9 — слоты; 0 — следующий слот; M — карта; Esc — пауза.\n\nСохранения привязаны к папке игры и профилю Edge. Используйте экспорт JSON\nв настройках для резервной копии или переноса. При запрете localStorage\nигра покажет предупреждение, JSON остаётся доступен.\n\nПолигон в главном меню открывает все 20 карт и чит-коды:\nCREDITS (+10000), AMMO, NORELOAD, GOD, ARSENAL.\nЧиты работают в копии профиля и не меняют сохранение кампании.\nВ паузе доступны отдельное отключение музыки и общий mute.\n',encoding='utf-8-sig')
with (OUT / 'README.txt').open('a', encoding='utf-8') as readme:
    readme.write(RECORDS_HELP)
    readme.write('\nМожно взять с собой только эту папку целиком, включая src.\nДля переноса прогресса сначала экспортируйте JSON в старой папке игры,\nзатем импортируйте его в настройках игры на новом месте.\n\nУсиления оружия: +12% базового урона за уровень, максимум +36%.\nВ карточке показан урон до/после покупки с учётом импланта усилителя.\n')
    readme.write('\nВерсия: ' + VERSION + '\n\nНовое развитие: до 5 зарядов рывка, импланты спринта, выносливости\nи лечения после зачистки волны. В магазине две независимые ветки оружия:\nурон и темп огня/особые свойства, по три ступени.\nПолный заряд рельсотрона проходит сквозь стены.\nВ настройках можно открыть бесконечный режим без прохождения кампании.\nВ миссиях 4 и 9 удерживайте E рядом с активированным передатчиком\nдля бесплатного ремонта (+30 HP/с). Стрельба при ремонте остановлена.\nBARRAGE — экспериментальная ракетница только на полигоне: темп ПП,\nбесконечные ракеты, без перезарядки. Код сразу выбирает оружие;\nесли введён до высадки, оно выбирается при старте миссии.\n')
with (OUT / 'README.txt').open('a', encoding='utf-8') as readme:
    readme.write('\nСохранения — три ручные ячейки в главном меню, паузе и выборе экспедиции.\nОни сохраняют весь профиль/контрольную точку отдельно от автосохранения.\nНовая кампания не удаляет ячейки; полный сброс удаляет.\nЭкспорт JSON включает активный профиль и все три ячейки.\nСтарый одиночный JSON импортируется без изменения ячеек.\n\nВ выборе экспедиции есть явный перезапуск с сектора 21: текущая точка\nсбрасывается после подтверждения, прокачка/деньги/рекорд сохраняются.\nПерезарядка начинается сразу после последнего выстрела при наличии резерва.\nПустой рельсотрон перезаряжается без попытки зарядить выстрел.\n\nПри каждом новом входе на полигон: 500000 кредитов и все улучшения в ноль.\nВнутри сессии магазин и повторная высадка сохраняют ваш эксперимент.\nОткрытая арена — большой прямоугольник без внутренних стен, вне кампании.\n')
shutil.make_archive(str(ROOT / 'XENOCIDE-offline'), 'zip', OUT)
print('Автономная сборка:', OUT)
